item.content:encoded:
{"styles":{"css":"```css
/* MAIN HEADER */
.finncare-header {
 width: 100%;
 gap: 0 !important;
}

/* TOP ROW */
.finncare-header-top {
 width: 100%;
 min-height: 100px;
 display: flex;
 align-items: center;
 justify-content: space-between;
 gap: 20px;
}

/* LOGO */
.finncare-header-top .wp-block-site-logo {
 flex: 0 0 auto;
}

.finncare-header-top .wp-block-site-logo img {
 display: block;
 width: 410px;
 height: auto;
 max-width: 100%;
}

/* TOP NAVIGATION */
.finncare-top-navigation {
 flex: 1 1 auto;
 justify-content: center;
}

.finncare-top-navigation .wp-block-navigation__container {
 display: flex;
 justify-content: center;
 gap: 40px;
}

/* LANGUAGE BUTTONS */
.finncare-language-buttons {
 flex: 0 0 auto;
 gap: 16px;
}

.finncare-language-buttons .wp-block-button__link {
 min-width: 120px;
 text-align: center;
 white-space: nowrap;
}

/* BOTTOM ROW */
.finncare-header-bottom {
 width: 100%;
 min-height: 55px;
 display: flex;
 align-items: center;
 justify-content: center;
}

/* BOTTOM NAVIGATION */
.finncare-bottom-navigation {
 width: 100%;
 justify-content: center;
}

.finncare-bottom-navigation .wp-block-navigation__container {
 display: flex;
 justify-content: center;
 gap: 30px;
}

/* SUBMENU ARROWS AND SPACING */
.finncare-bottom-navigation .wp-block-navigation-item {
 white-space: nowrap;
}

/* TABLETS AND SMALLER SCREENS */
@media (max-width: 1199px) {
 .finncare-header-top {
 flex-wrap: wrap;
 justify-content: center;
 padding: 15px;
 }

 .finncare-header-top .wp-block-site-logo img {
 width: 300px;
 }

 .finncare-top-navigation {
 flex: 1 1 100%;
 justify-content: center;
 }

 .finncare-top-navigation .wp-block-navigation__container,
 .finncare-bottom-navigation .wp-block-navigation__container {
 flex-wrap: wrap;
 gap: 20px;
 }
}

/* MOBILE */
@media (max-width: 600px) {
 .finncare-header-top .wp-block-site-logo img {
 width: 240px;
 }

 .finncare-language-buttons {
 justify-content: center;
 flex-wrap: wrap;
 }

 .finncare-top-navigation .wp-block-navigation__container,
 .finncare-bottom-navigation .wp-block-navigation__container {
 flex-direction: column;
 align-items: center;
 gap: 12px;
 }

 .finncare-header-bottom {
 padding: 15px 0;
 }
}
```
"},"settings":{"layout":{"contentSize":"1920px","wideSize":"1250px"}},"isGlobalStylesUserThemeJSON":true,"version":3}
